python3 -c "
# Extended search for smallest perfect cube n^3 expressible as sum of two different positive cubes in two different ways
# n^3 = a^3 + b^3 = c^3 + d^3 with 0 < a < b < n and 0 < c < d < n

# Use a hash map for cube lookups
max_n = 20000
cube_to_root = {}
for i in range(1, max_n):
    cube_to_root[i**3] = i

found = False
for n in range(2, max_n):
    target = n**3
    ways = []
    # Only check a where a^3 < target/2 (since a < b, a^3 < target/2)
    for a in range(1, int((target/2)**(1/3)) + 2):
        rem = target - a**3
        if rem in cube_to_root:
            b = cube_to_root[rem]
            if a < b < n:
                ways.append((a, b))
        if len(ways) >= 2:
            break
    if len(ways) >= 2:
        print(f'{n}^3 = {target}')
        for w in ways:
            print(f'  {w[0]}^3 + {w[1]}^3 = {w[0]**3} + {w[1]**3} = {target}')
        found = True
        break

if not found:
    print(f'No solution found for n < {max_n}')
" 2>&1
"
